(()=>{
  'use strict';
  const ADMIN='service.battermann@gmx.de';let installed=false,inflight=null,attempts=0;
  const owner=cloud=>String(cloud?.user?.email||'').trim().toLowerCase()===ADMIN;
  function normalize(payload,cloud){const data=payload&&typeof payload==='object'?payload:{},sub=data.subscription&&typeof data.subscription==='object'?data.subscription:{plan:'free',status:'active'},addon=data.addon&&typeof data.addon==='object'?data.addon:null,active=['active','trialing'].includes(String(sub.status||'')),paid=active&&['pro','ultimate'].includes(sub.plan)?sub.plan:'free',isOwner=owner(cloud),plan=isOwner?'ultimate':paid,personal=Array.isArray(data.aiConnections)?data.aiConnections:[],cfg=cloud?.config||{},profiles=Array.isArray(cfg.systemAiProfiles)?cfg.systemAiProfiles:[],providers=[...new Set([...(cfg.previewProviders||[]),...(cfg.systemAiProviders||[]),...profiles.filter(x=>x.enabled!==false).map(x=>x.provider)])],connections=[...personal];for(const provider of providers)if(provider&&!connections.some(x=>x.provider===provider))connections.push({provider,last4:'zentral',updated_at:null,system:true});if(profiles.some(x=>x.enabled!==false&&(x.tasks||[]).includes('image'))&&!connections.some(x=>x.provider==='auto'))connections.push({provider:'auto',last4:'zentral',updated_at:null,system:true});return{settings:data.settings?.data||null,activeProfileId:data.settings?.active_profile_id||'',profiles:Array.isArray(data.profiles)?data.profiles:[],templates:Array.isArray(data.templates)?data.templates:[],modules:Array.isArray(data.modules)?data.modules:[],skills:(Array.isArray(data.skills)?data.skills:[]).map(x=>({...x,sourceFile:x.source_file||x.sourceFile||null})),projects:Array.isArray(data.projects)?data.projects:[],aiConnections:connections,subscription:{...sub,plan,status:sub.status||'active',isAdmin:isOwner||Boolean(data.isAdmin),ownApiKeys:isOwner||plan==='ultimate'||(['active','trialing'].includes(addon?.status))},userProfile:data.userProfile?{displayName:data.userProfile.display_name||'',companyName:data.userProfile.company_name||'',website:data.userProfile.website||'',defaultClientType:data.userProfile.default_client_type||''}:null,reviewCredits:Number(data.reviewCredits)||0}}
  function install(){const cloud=window.SiteBriefCloud;if(installed||!cloud?.loadUserBundle||!cloud?.client)return false;const native=cloud.loadUserBundle.bind(cloud);cloud.loadUserBundle=async function(){if(!cloud.user)return native();if(inflight)return inflight;inflight=(async()=>{try{const {data,error}=await cloud.client.rpc('sitebrief_load_user_bundle');if(error||!data)throw error||new Error('Bundle RPC unavailable');return normalize(data,cloud)}catch{return native()}finally{setTimeout(()=>{inflight=null},0)}})();return inflight};cloud.loadUserBundle.__promptFastBundle=true;installed=true;return true}
  if(!install()){const timer=setInterval(()=>{if(install()||++attempts>80)clearInterval(timer)},40);window.SiteBriefCloudReady?.then?.(()=>install()).catch?.(()=>{})}
})();
